llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C43"],
      "claim": "Oral uridine, a natural ribonucleoside with high polarity, has an absolute oral bioavailability of ~7% in humans, demonstrating that unmodified ribonucleosides can be poorly absorbed despite transporter availability; this supports low F for guanosine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "NHC, a ribonucleoside analog, is reported to have poor human oral bioavailability, supporting that highly polar ribonucleosides without metabolic stabilization are poorly absorbed; this supports low F for guanosine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Cladribine, a 2-chloro-2'-deoxyadenosine, has oral bioavailability ~48% in patients; although structurally similar, its deoxyribose and halogen substitution increase lipophilicity and metabolic stability, so this high-F evidence is only weakly transferable to unmodified guanosine and is contradictory to the low prediction.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C34"],
      "claim": "Fludarabine, a 2-fluoroadenine arabinoside, has oral bioavailability 50–65%; its arabinose and fluorine modifications confer resistance to metabolic cleavage, making this high-F evidence less applicable to guanosine; contradictory.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C17"],
      "claim": "Ribavirin, a polar ribonucleoside, has oral bioavailability 45–65%; however, its triazole carboxamide base is not a purine nucleoside phosphorylase substrate, so its absorption does not reflect the metabolic lability of guanosine; contradictory.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Guanosine is an unmodified, highly polar purine ribonucleoside that is a substrate for purine nucleoside phosphorylase and likely undergoes extensive first-pass glycosidic cleavage, similar to uridine and NHC which show poor oral bioavailability. The high oral bioavailability of cladribine, fludarabine, and ribavirin is attributable to metabolic-stabilizing modifications and is less transferable. Therefore, F < 20% is better supported.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for guanosine itself in humans or animals.",
    "Lack of quantitative data on guanosine's intestinal nucleoside transporter affinity versus its PNP-mediated first-pass metabolism.",
    "Uncertainty about whether any active transport could overcome the expected poor passive permeability and metabolic lability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

